(352849, 27571, 7763, '<td valign="top">funny</td>', 'funny', '2003-07-11 01:18:25.000000', NULL, 1),
(352850, 28288, 806, '<td valign="top">nice skin tones, and pose... would like to see a different angle of the camera on this one. I like how you took time on the hair .. lighting shows body details nicely.</td>', 'nice skin tones, and pose... would like to see a different angle of the camera on this one. I like how you took time on the hair .. lighting shows body details nicely.', '2003-07-11 01:19:01.000000', NULL, 1),
