(353538, 28222, 3087, '<td valign="top">An absolutely great example of someone really enjoying the warmth of the sun upon their skin. And, look, a little nipple poking out! I feel a strange kinship with this entry! (See my SP Revisited entry LOL).<br/>Great background too - fantastic shapes and texture to it but softness too.<br/>Lighting and skin tone seems just right.<br/>One of my favourites.</td>', 'An absolutely great example of someone really enjoying the warmth of the sun upon their skin. And, look, a little nipple poking out! I feel a strange kinship with this entry! (See my SP Revisited entry LOL).Great background too - fantastic shapes and texture to it but softness too.Lighting and skin tone seems just right.One of my favourites.', '2003-07-11 11:44:36.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(353539, 28281, 327, '<td valign="top">Cute femme-Bot.   I think you needed some color here. She has a perfect body for nude photos ....IMHO.<br/>This just looks a bit blah to me. Maybe having her hair down on a darker background? <br/>No matter this is nice. I like her, the light and the pose. Good work!</td>', 'Cute femme-Bot.   I think you needed some color here. She has a perfect body for nude photos ....IMHO.This just looks a bit blah to me. Maybe having her hair down on a darker background? No matter this is nice. I like her, the light and the pose. Good work!', '2003-07-11 11:45:32.000000', NULL, 1),
(353540, 27841, 3087, '<td valign="top">What a clever use of light projection - this is such a quirky and unusual image. Just a touch dark for my preferences but still one of my favourites in this challenge.</td>', 'What a clever use of light projection - this is such a quirky and unusual image. Just a touch dark for my preferences but still one of my favourites in this challenge.', '2003-07-11 11:45:45.000000', NULL, 1),
