(354160, 27974, 7994, '<td valign="top">i think more blueish tones would make a greater impression, love the composition though</td>', 'i think more blueish tones would make a greater impression, love the composition though', '2003-07-11 20:01:28.000000', NULL, 1),
(354161, 28274, 6600, '<td valign="top">Love this shot! Super !!!!</td>', 'Love this shot! Super !!!!', '2003-07-11 20:03:31.000000', NULL, 1),
