(359533, 27976, 9884, '<td valign="top">Beautiful Photograph,  unique,  I really like the texture of the material around the baby!!!  Soft as clouds, just as a child should be, shadows are great!!!</td>', 'Beautiful Photograph,  unique,  I really like the texture of the material around the baby!!!  Soft as clouds, just as a child should be, shadows are great!!!', '2003-07-17 01:49:54.000000', NULL, 1),
